+    private static let textureCORSScript = #"""
+        if(location.origin!=='https://play.yunle.fun'||location.pathname!=='/'||location.search||location.hash||document.documentElement.dataset.appReady!=='true')
+          throw Error('unexpected diagnostic homepage');
+        const required=[
+          {asset:'planes',url:'https://assets.play.yunle.fun/games/paper-star/runtime/v2/planes.png?webgl=1'},
+          {asset:'world-sprites',url:'https://assets.play.yunle.fun/games/paper-star/runtime/v2/world-sprites.png?webgl=1'}
+        ];
+        const violations=[];
+        const violation=event=>{
+          if(violations.length>=8)return;
+          let scope=null;
+          try{const u=new URL(event.blockedURI);if(u.origin==='https://assets.play.yunle.fun'){
+            scope=required.find(a=>new URL(a.url).pathname===u.pathname)?.asset||'assets-origin';}}catch{}
+          if(!scope)return;
+          const directives=['connect-src','img-src','default-src'];
+          violations.push({asset:scope,effectiveDirective:directives.includes(event.effectiveDirective)?event.effectiveDirective:'other',
+            disposition:event.disposition==='enforce'?'enforce':'report'});
+        };
+        document.addEventListener('securitypolicyviolation',violation);
+        let assets;
+        try {
+          assets=await Promise.all(required.map(async item=>{
+            const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),8000);
+            const result={asset:item.asset,publicURL:item.url,success:false,status:null,type:null,contentType:null,bytes:null,sha256:null,errorName:null};
+            try {
+              const response=await fetch(item.url,{mode:'cors',credentials:'omit',redirect:'error',cache:'reload',signal:controller.signal});
+              result.status=response.status;result.type=['basic','cors','opaque','error','opaqueredirect'].includes(response.type)?response.type:'other';
+              result.contentType=(response.headers.get('content-type')||'').slice(0,100);
+              const bytes=await response.arrayBuffer();result.bytes=bytes.byteLength;
+              const hash=await crypto.subtle.digest('SHA-256',bytes);
+              result.sha256=[...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('');
+              result.success=response.ok;
+            } catch(error) {
+              result.errorName=['TypeError','AbortError','SecurityError','NotAllowedError','Error'].includes(error?.name)?error.name:'UnknownError';
+            } finally {clearTimeout(timer);}
+            return result;
+          }));
+        } finally {document.removeEventListener('securitypolicyviolation',violation);}
+        return JSON.stringify({assets,cspViolations:violations,credentials:'omit',mode:'cors',redirect:'error',cache:'reload',perRequestAbortMS:8000,
+          interpretation:'CORS-readable bytes and SHA support only these exact public texture requests, not renderer/game readiness; failures retain safe error name without credential or request-header inspection.'});
