+    private func clearLegacyHTTPCache(_ identifier: UUID) async throws -> [String: Any] {
+        // This temporary wrapper refers to the same owned UUID. It is released
+        // on return before timed open; no additional WebView/store is kept warm.
+        let store = WKWebsiteDataStore(forIdentifier: identifier)
+        let completed = LegacyHTTPSCallback<Bool>()
+        let started = ProcessInfo.processInfo.systemUptime
+        let types: Set<String> = [WKWebsiteDataTypeMemoryCache, WKWebsiteDataTypeDiskCache]
+        store.removeData(ofTypes: types, modifiedSince: .distantPast) { completed.value = true }
+        let deadline = started + 20
+        while completed.value == nil && ProcessInfo.processInfo.systemUptime < deadline {
+            try await Task.sleep(nanoseconds: 20_000_000)
+        }
+        guard completed.value == true else { throw LegacyHTTPSFailure(code: 44) }
+        return ["profileUUID": identifier.uuidString, "types": types.sorted(),
+                "startedUptime": started, "completedUptime": ProcessInfo.processInfo.systemUptime,
+                "cookiesLocalStorageIndexedDBPreserved": true]
+    }
+
+    private func endLegacyTrial(_ fixture: LegacyHTTPSFixture, page: LegacyHTTPSWeakWeb) async throws -> [String: Any] {
+        let started = ProcessInfo.processInfo.systemUptime
+        fixture.runtime.end(fixture.application)
+        let deadline = started + 15
+        while ProcessInfo.processInfo.systemUptime < deadline {
+            if fixture.root.presentedViewController == nil, !fixture.runtime.contains(fixture.application), page.web == nil {
+                return ["startedUptime": started, "completedUptime": ProcessInfo.processInfo.systemUptime,
+                        "presentationDismissed": true, "sessionRemoved": true, "previousWKWeakReleased": true,
+                        "nextOpenMustCreateFreshWK": true]
+            }
+            try await Task.sleep(nanoseconds: 50_000_000)
+        }
+        throw LegacyHTTPSFailure(code: 45)
+    }
