+        let web = try XCTUnwrap(browser.viewIfLoaded?.subviews.compactMap { $0 as? WKWebView }.first)
+        try fixture.track(web)
+        evidence.nativePresentation = fixture.presentation(web)
+        guard fixture.isVisible(web) else { throw LegacyHTTPSFailure(code: 10) }
+        let home = try await wait(web, path: "/") { ($0["appReady"] as? Bool) == true }
+        evidence.record("home-observed", home)
+        try await click(web, selector: ".game-grid .game-card[data-game='\(game)'] a.game-card-link[href]",
+                        path: "/games/\(game)", evidence: evidence)
+        let detailPath = "/games/\(game)"
+        let detail = try await wait(web, path: detailPath) { ($0["appReady"] as? Bool) == true }
+        evidence.record("detail-observed", detail)
+        let modePath = detailPath + "/" + mode
+        try await click(web, selector: ".detail-page[data-game='\(game)'] .detail-actions a[href]", path: modePath, evidence: evidence)
