+            let controls = try await wait(web, path: modePath) {
+                ($0["gomokuCellEnabled"] as? Bool) == true
+            }
+            evidence.record("gomoku-controls-observed-not-worker-proof", controls)
+            let blackBefore = controls["black"] as? Int ?? 0
+            let whiteBefore = controls["white"] as? Int ?? 0
+            _ = try await evaluate(web, """
+                (() => { \(Self.snapshotHelpers)
+                  guardPage('\(modePath)');
+                  const cell=document.querySelector('.gomoku-board [data-testid="cell-7-7"]');
+                  if(!visible(cell)||cell.getAttribute('aria-disabled')==='true'||cell.querySelector('.stone')) throw Error('cell unavailable');
+                  cell.click(); return JSON.stringify({clicked:true});
+                })()
+                """)
+            let black = try await wait(web, path: modePath) { ($0["black"] as? Int ?? 0) > blackBefore }
+            evidence.record("gomoku-actual-human-black-observed", black)
+            let white = try await wait(web, path: modePath) {
+                ($0["white"] as? Int ?? 0) > whiteBefore && ($0["gomokuAnyEmptyCellEnabled"] as? Bool) == true
+            }
