+    private func click(_ web: WKWebView, selector: String, path: String, evidence: LegacyHTTPSObservation) async throws {
+        // Find and scroll the rendered anchor; never load its URL directly.
+        let selected = "\(selector)[href='\(path)']"
+        try await scroll(web, selector: selected, evidence: evidence, phase: "public-link-scroll")
+        let result = try await evaluate(web, """
+            (() => { \(Self.snapshotHelpers)
+              if(location.origin!=='https://play.yunle.fun'||location.search||location.hash||document.documentElement.dataset.appReady!=='true') throw Error('unexpected source');
+              const anchor=[...document.querySelectorAll("\(selector)")].find(a=>{
+                const u=new URL(a.href,location.href);
+                return u.origin==='https://play.yunle.fun'&&u.pathname==='\(path)'&&!u.search&&!u.hash&&!u.username&&!u.password;
+              });
+              if(!visible(anchor)) throw Error('visible public link missing');
+              anchor.click(); return JSON.stringify({clickedPath:'\(path)'});
+            })()
+            """)
+        evidence.record("public-link-click", result)
+    }
+
+    private func scroll(_ web: WKWebView, selector: String, evidence: LegacyHTTPSObservation, phase: String) async throws {
+        let observation = try await evaluate(web, """
+            (() => { \(Self.snapshotHelpers)
+              if(location.origin!=='https://play.yunle.fun'||location.search||location.hash) throw Error('unexpected source');
+              const element=document.querySelector("\(selector)");
+              if(!element) throw Error('scroll target missing');
+              const before=rect(element),beforeFraction=fraction(element);
+              const requested=beforeFraction<1;
+              if(requested) element.scrollIntoView({block:'center',inline:'nearest',behavior:'auto'});
+              return JSON.stringify({requested,before,beforeFraction,scrollX,scrollY});
+            })()
+            """)
+        evidence.record(phase + "-requested", observation)
+        let deadline = ProcessInfo.processInfo.systemUptime + 5
+        var previous: [Double] = []
+        var stable = 0
+        while ProcessInfo.processInfo.systemUptime < deadline {
+            let value = try await evaluate(web, """
+                (() => { \(Self.snapshotHelpers)
+                  const element=document.querySelector("\(selector)");
+                  return JSON.stringify({visible:visible(element),rect:rect(element),fraction:fraction(element),scrollX,scrollY,
+                    viewport:{width:innerWidth,height:innerHeight}});
+                })()
+                """)
+            if let rect = value["rect"] as? [String: Any], let x = rect["x"] as? Double, let y = rect["y"] as? Double {
+                let current = [x, y]
+                stable = previous == current ? stable + 1 : 0
+                previous = current
+                if value["visible"] as? Bool == true && stable >= 2 {
+                    evidence.record(phase + "-settled", value)
+                    return
+                }
+            }
+            lastSnapshot = value
+            try await Task.sleep(nanoseconds: 50_000_000)
+        }
+        throw LegacyHTTPSFailure(code: 23)
+    }
+
+    private func wait(_ web: WKWebView, path: String, condition: ([String: Any]) -> Bool) async throws -> [String: Any] {
+        let deadline = ProcessInfo.processInfo.systemUptime + 45
+        while ProcessInfo.processInfo.systemUptime < deadline {
+            try Task.checkCancellation()
+            if let value = try? await evaluate(web, Self.snapshotScript) {
+                lastSnapshot = value
+                if value["path"] as? String == path, value["publicOrigin"] as? Bool == true,
+                   value["visible"] as? Bool == true, condition(value) { return value }
+            }
+            try await Task.sleep(nanoseconds: 50_000_000)
+        }
+        // No navigation fallback: a changed/missing public DOM is a preflight failure.
+        throw LegacyHTTPSFailure(code: 20)
+    }
+
+    private func evaluate(_ web: WKWebView, _ script: String) async throws -> [String: Any] {
+        let box = LegacyHTTPSCallback<Result<Any?, Error>>()
+        web.evaluateJavaScript(script) { value, error in
+            box.value = error.map(Result.failure) ?? .success(value)
+        }
+        let deadline = ProcessInfo.processInfo.systemUptime + 5
+        while ProcessInfo.processInfo.systemUptime < deadline {
+            if let result = box.value {
+                guard let string = try result.get() as? String,
+                      let object = try JSONSerialization.jsonObject(with: Data(string.utf8)) as? [String: Any] else {
+                    throw LegacyHTTPSFailure(code: 21)
+                }
+                return object
+            }
+            try await Task.sleep(nanoseconds: 20_000_000)
+        }
+        throw LegacyHTTPSFailure(code: 22)
+    }
