+    private static func spaceScript(type: String, path: String) -> String {
+        """
+        (() => { \(snapshotHelpers) guardPage('\(path)');
+          window.dispatchEvent(new KeyboardEvent('\(type)',{key:' ',code:'Space',bubbles:true,cancelable:true}));
+          return JSON.stringify({type:'\(type)',syntheticPublicKeyboardEvent:true}); })()
+        """
+    }
